"""llm-dojo-scoring — the scoring engine for LLM document pipelines.

Field-type-aware extraction scoring, classification metrics, per-agent suites,
uncertainty and failure reporting for llm-mailroom and the sandbox.

Every name below is resolved lazily (PEP 562): ``import llm_dojo_scoring`` loads
only the legacy-path finder, and ``llm_dojo_scoring.<name>`` imports the module
that defines ``<name>`` on first access. To export a new root name, add it to
``_LAZY`` (name -> (defining module, attribute)) and to ``__all__``.
"""

from __future__ import annotations

import importlib
from typing import Any

