def __getattr__(name: str) -> Any:
    """Import and cache a root name or submodule on first access (PEP 562)."""
    if name in _LAZY:
        module, attr = _LAZY[name]
        value = getattr(importlib.import_module(f"{__name__}.{module}" if module else __name__), attr)
    elif name in _SUBMODULES:
        value = importlib.import_module(f"{__name__}.{_SUBMODULES[name]}")
    elif name in _REMOVED:
        raise AttributeError(
            f"llm_dojo_scoring.{name} was removed in the production slim-down; "
            "see CHANGELOG.md (Unreleased, Removed) for why, and for its replacement where one exists"
        )
    else:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
    globals()[name] = value
    return value


def __dir__() -> list[str]:
    """List eager globals plus every lazily resolvable name."""
    return sorted(set(globals()) | set(_LAZY) | set(_SUBMODULES))
